#!/usr/bin/env bash
# Some portions generated by Codex. Run only during the owner's granted measurement window.
set -euo pipefail
cd "$(dirname "$0")/../.."
: "${CP_A:?Frozen baseline classpath required}"
: "${CP_B:?Frozen candidate classpath required}"
: "${LOCK:?Absolute coordinated measurement lock required}"
JAVA=${JAVA:-../toolchain/jdk-25.0.5+8/bin/java}
JAVAC=${JAVAC:-../toolchain/jdk-25.0.5+8/bin/javac}
OUT=${OUT:-experiments/threadlocal-audit/runs-$(date -u +%Y%m%dT%H%M%SZ)}
mkdir -p "$OUT/harness" "$OUT/tmp"
# No target/ or Maven writes. One common harness binary, never compile production here.
"$JAVAC" -cp "$CP_B" -d "$OUT/harness" experiments/threadlocal-audit/ThreadLocal{Query,CoScan}Benchmark.java
HARNESS=$(realpath "$OUT/harness")
FIXTURE=$(realpath -m "$OUT/fixture")
{
 date -u; echo candidatePublished=c02f684d78bce58d1c8f2710cb9bb2aa8bed5dfa; echo baselineSource=ba74f4782e95e386653a6b1c7f6b0969e09b8f12; echo localHeadOnlyNotCandidate:; git rev-parse HEAD; "$JAVA" -version; printf 'CP_A=%s\nCP_B=%s\nLOCK=%s\n' "$CP_A" "$CP_B" "$LOCK"
 sha256sum experiments/threadlocal-audit/ThreadLocal*Benchmark.java
 find experiments/threadlocal-audit/candidate-classes experiments/threadlocal-audit/baseline-type-matrix -name '*.class' -type f -print0 | sort -z | xargs -0 sha256sum > "$OUT/classes.sha256"
 sha256sum core/sail/lmdb/src/main/java/org/eclipse/rdf4j/sail/lmdb/evaluation/{NativeCancellationCheckpoint,LmdbNativeTypeMatrix}.java > "$OUT/sources.sha256"
} > "$OUT/environment.txt" 2>&1
FLAGS=(-Drdf4j.lmdb.queryMemory.perQueryMaxBytes=671088640)
# Additional flags must be an owner-reviewed newline-delimited file; no eval/shell injection.
if [[ -n ${FLAGS_FILE:-} ]]; then mapfile -t EXTRA < "$FLAGS_FILE"; FLAGS+=("${EXTRA[@]}"); fi
printf '%s\n' "${FLAGS[@]}" > "$OUT/flags.txt"
exec 9>"$LOCK"
flock 9
run() {
 local cp=$1 log=$2; shift 2
 "$JAVA" --enable-native-access=ALL-UNNAMED -Xms2g -Xmx3g "-Djava.io.tmpdir=$(realpath "$OUT/tmp")" \
   "${FLAGS[@]}" "$@" -cp "$HARNESS:$cp" org.eclipse.rdf4j.sail.lmdb.evaluation.ThreadLocalQueryBenchmark \
   "${GROUPS_COUNT:-100}" 10 "${ITERATIONS:-10}" true > "$log" 2>&1
}
# Fresh regular reference determines BOTH checksums across all variants and forks.
run "$CP_A" "$OUT/reference.log" -Daudit.regime=regular -Daudit.shape=narrow \
 -Doverlay.benchmark.fixture="$FIXTURE" -Doverlay.benchmark.warmups=0
for regime in ${REGIMES:-regular interpreted janino}; do
 i=0
 for variant in A B B A B A A B; do
  i=$((i+1)); cp=$CP_A; [[ $variant == B ]] && cp=$CP_B
  run "$cp" "$OUT/$regime-$i-$variant.log" -Daudit.regime="$regime" -Daudit.shape=narrow \
   -Doverlay.benchmark.fixture="$FIXTURE" -Doverlay.benchmark.warmups="${WARMUPS:-5}"
 done
done
i=0
for variant in A B B A B A A B; do
 i=$((i+1)); cp=$CP_A; [[ $variant == B ]] && cp=$CP_B
 "$JAVA" --enable-native-access=ALL-UNNAMED -Xms2g -Xmx3g "${FLAGS[@]}" \
   -Daudit.warmups="${WARMUPS:-5}" -cp "$HARNESS:$cp" \
   org.eclipse.rdf4j.sail.lmdb.evaluation.ThreadLocalCoScanBenchmark "${COSCAN_GROUPS:-1000}" "${ITERATIONS:-10}" \
   > "$OUT/coscan-$i-$variant.log" 2>&1
done
python3 experiments/threadlocal-audit/summarize-matched.py "$OUT" > "$OUT/summary.json"
cat "$OUT/summary.json"
